<?php
declare(strict_types=1);
require __DIR__.'/lib/bootstrap.php';
require __DIR__.'/lib/layout.php';
require_permission('settings.read');
$error=null;
if(($_SERVER['REQUEST_METHOD']??'')==='POST'){
    try{verify_csrf();require_permission('settings.update');
        foreach($_POST['module_enabled']??[] as $key=>$value) db()->prepare('UPDATE cms_modules SET is_enabled=? WHERE module_key=?')->execute([(int)$value,$key]);
        if((string)($_POST['modules_form']??'')==='1') foreach(cfg('modules',[]) as $key=>$def) if(!array_key_exists($key,$_POST['module_enabled']??[])) db()->prepare('UPDATE cms_modules SET is_enabled=0 WHERE module_key=? AND module_key NOT IN("media","settings","users","roles","audit")')->execute([$key]);
        foreach($_POST['setting']??[] as $key=>$value) db()->prepare('INSERT INTO cms_settings(setting_key,setting_value,updated_by) VALUES(?,?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),updated_by=VALUES(updated_by)')->execute([$key,(string)$value,current_user()['id']]);
        audit('settings.update','settings'); flash('Settings saved.'); redirect('settings.php');
    }catch(Throwable $e){$error=$e->getMessage();}
}
$enabled=[];foreach(db()->query('SELECT module_key,is_enabled FROM cms_modules')->fetchAll() as $row)$enabled[$row['module_key']]=(int)$row['is_enabled'];
$settings=[];foreach(db()->query('SELECT setting_key,setting_value FROM cms_settings')->fetchAll() as $row)$settings[$row['setting_key']]=$row['setting_value'];
page_start('Site Settings','settings');
?><div class="page-head"><div><span class="eyebrow">SYSTEM</span><h2>Settings & modules</h2><p class="muted">Each copied website can enable only the features it needs.</p></div></div><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post" id="settingsForm" data-ajax-form data-success="Settings saved successfully."><?=csrf_field()?><input type="hidden" name="modules_form" value="1"><section class="panel"><div class="panel-head"><div><h3>Module manager</h3><p class="muted">Disabled modules disappear from navigation and cannot be accessed.</p></div></div><div class="module-settings"><?php foreach(cfg('modules',[]) as $key=>$def):?><label class="module-toggle"><input type="hidden" name="module_enabled[<?=e($key)?>]" value="0"><input type="checkbox" name="module_enabled[<?=e($key)?>]" value="1" <?=$enabled[$key]??1?'checked':''?> <?=($def['system']??false)&&in_array($key,['media','settings','users','roles','audit'],true)?'disabled':''?>><span><strong><?=e($def['label'])?></strong><small><?=e($def['group']??'Module')?> · <?=($def['system']??false)?'System module':'Content module'?></small></span></label><?php endforeach;?></div></section><section class="panel"><h3>Site profile</h3><div class="form-grid"><label>Site name<input name="setting[site.name]" value="<?=e($settings['site.name']??'')?>" placeholder="e.g. ResourceField Limited"></label><label>Site URL<input type="url" name="setting[site.url]" value="<?=e($settings['site.url']??'')?>" placeholder="https://www.example.com"></label><label>Default SEO title<input name="setting[seo.title]" value="<?=e($settings['seo.title']??'')?>" placeholder="e.g. Leading environmental consultancy in Nigeria"></label><label>Default SEO description<textarea name="setting[seo.description]" rows="3" placeholder="Describe the website for search engines in 150 to 160 characters."><?=e($settings['seo.description']??'')?></textarea></label><label>Admin notification email<input type="email" name="setting[mail.admin_email]" value="<?=e($settings['mail.admin_email']??'')?>" placeholder="admin@example.com"></label><label>Timezone<input name="setting[site.timezone]" value="<?=e($settings['site.timezone']??'Africa/Lagos')?>" placeholder="e.g. Africa/Lagos"></label></div></section><section class="panel"><h3>Outgoing mail (SMTP)</h3><p class="muted">PHP's built-in mail() rarely delivers reliably. Configure SMTP so messages sent from Mail &amp; Templates actually reach recipients.</p><div class="form-grid"><label class="module-toggle"><input type="hidden" name="setting[mail.smtp_enabled]" value="0"><input type="checkbox" name="setting[mail.smtp_enabled]" value="1" <?=($settings['mail.smtp_enabled']??'')==='1'?'checked':''?>><span><strong>Send mail via SMTP</strong><small>When off, the server's local mail() function is used instead.</small></span></label><label>SMTP host<input name="setting[mail.smtp_host]" value="<?=e($settings['mail.smtp_host']??'')?>" placeholder="e.g. smtp.gmail.com or 127.0.0.1"></label><label>SMTP port<input type="number" name="setting[mail.smtp_port]" value="<?=e($settings['mail.smtp_port']??'587')?>" placeholder="587"></label><label>Encryption<select name="setting[mail.smtp_encryption]"><?php foreach(['tls'=>'STARTTLS (587)','ssl'=>'SSL/TLS (465)','none'=>'None (local testing only)'] as $value=>$label):?><option value="<?=e($value)?>" <?=($settings['mail.smtp_encryption']??'tls')===$value?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></label><label>SMTP username<input name="setting[mail.smtp_username]" value="<?=e($settings['mail.smtp_username']??'')?>" placeholder="Leave blank if the server needs no authentication" autocomplete="off"></label><label>SMTP password<input type="password" name="setting[mail.smtp_password]" value="<?=e($settings['mail.smtp_password']??'')?>" placeholder="Leave blank if the server needs no authentication" autocomplete="new-password"></label><label>From email<input type="email" name="setting[mail.from_email]" value="<?=e($settings['mail.from_email']??'')?>" placeholder="no-reply@example.com"></label><label>From name<input name="setting[mail.from_name]" value="<?=e($settings['mail.from_name']??'')?>" placeholder="e.g. Master CMS"></label></div></section><button class="button primary">Save settings</button></form><?php page_end();
